import json

def transform(grid):
    # Get the special value (non-zero value in grid)
    special_value = None
    for row in grid:
        for cell in row:
            if cell != 0:
                special_value = cell
                break
        if special_value:
            break

    result = []
    for row in grid:
        new_row = []
        for cell in row:
            if cell == 0:
                # Background: if special is even, 0→2; if special is odd, 0→0
                if special_value % 2 == 0:
                    new_row.append(2)
                else:
                    new_row.append(0)
            else:
                # Special value: if even→0, if odd→1
                if special_value % 2 == 0:
                    new_row.append(0)
                else:
                    new_row.append(1)
        result.append(new_row)
    return result

