import json

def transform(grid):
    non_zero_values = [cell for row in grid for cell in row if cell != 0]
    special_value = non_zero_values[0]

    if special_value > 4:
        background_constant = special_value // 4
    else:
        background_constant = special_value // 3

    result = []
    for row in grid:
        new_row = []
        for cell in row:
            if cell == 0:
                new_row.append(background_constant)
            else:
                new_row.append(0)
        result.append(new_row)
    return result

test_in = [[3, 0, 0], [3, 3, 3], [0, 0, 3]]
test_out = transform(test_in)
print(json.dumps(test_out))
